R implementation
We implement the spatial PD with Moore neighbourhood, periodic boundaries, and synchronous deterministic update.

# --- Lattice setup ---
L &lt;- 50  # grid size
b &lt;- 1.8  # temptation to defect
n_gen &lt;- 100

# Initialize: cooperators (1) everywhere, single defector seed at centre
set.seed(42)
grid &lt;- matrix(1L, nrow = L, ncol = L)  # 1 = C, 0 = D
# Seed 10% random defectors
n_defectors &lt;- round(0.1 * L^2)
defector_idx &lt;- sample(L^2, n_defectors)
grid[defector_idx] &lt;- 0L

# Periodic boundary helper
wrap &lt;- function(idx, L) ((idx - 1L) %% L) + 1L

# Compute total payoff for each cell
compute_scores &lt;- function(grid, b, L) {
  scores &lt;- matrix(0, nrow = L, ncol = L)
  for (di in -1:1) {
    for (dj in -1:1) {
      # Neighbour indices with wrapping
      ni &lt;- wrap(1:L + di, L)
      nj &lt;- wrap(1:L + dj, L)
      neighbour &lt;- grid[ni, nj]
      # Payoff: C vs C = 1, D vs C = b, C vs D = 0, D vs D = 0
      scores &lt;- scores + ifelse(grid == 1L, neighbour, b * neighbour)
    }
  }
  scores
}

# Update: each cell adopts strategy of highest-scoring neighbour (including self)
update_grid &lt;- function(grid, scores, L) {
  new_grid &lt;- grid
  for (i in 1:L) {
    for (j in 1:L) {
      best_score &lt;- scores[i, j]
      best_strat &lt;- grid[i, j]
      for (di in -1:1) {
        for (dj in -1:1) {
          if (di == 0 && dj == 0) next
          ni &lt;- wrap(i + di, L)
          nj &lt;- wrap(j + dj, L)
          if (scores[ni, nj] &gt; best_score) {
            best_score &lt;- scores[ni, nj]
            best_strat &lt;- grid[ni, nj]
          }
        }
      }
      new_grid[i, j] &lt;- best_strat
    }
  }
  new_grid
}

# --- Run simulation ---
coop_freq &lt;- numeric(n_gen + 1)
coop_freq[1] &lt;- mean(grid)

snapshots &lt;- list()
snapshot_gens &lt;- c(0, 5, 20, 50, 100)

for (g in 1:n_gen) {
  if ((g - 1) %in% snapshot_gens) {
    snapshots[[as.character(g - 1)]] &lt;- grid
  }
  scores &lt;- compute_scores(grid, b, L)
  grid &lt;- update_grid(grid, scores, L)
  coop_freq[g + 1] &lt;- mean(grid)
}
snapshots[[as.character(n_gen)]] &lt;- grid

cat(sprintf("Cooperation frequency: start=%.3f, end=%.3f (b=%.1f, L=%d)\n",
            coop_freq[1], coop_freq[n_gen + 1], b, L))

Cooperation frequency: start=0.900, end=0.360 (b=1.8, L=50)

R implementation
We implement the spatial Prisoner’s Dilemma on a 30x30 grid with periodic boundary conditions and run the simulation for 100 rounds.

set.seed(42)

N &lt;- 30
n_rounds &lt;- 100
b_temptation &lt;- 1.5

R_pay &lt;- 1; S_pay &lt;- -0.5; T_pay &lt;- b_temptation; P_pay &lt;- 0

pd_payoff &lt;- function(s_me, s_other) {
  if (s_me == 1 && s_other == 1) return(R_pay)
  if (s_me == 1 && s_other == 0) return(S_pay)
  if (s_me == 0 && s_other == 1) return(T_pay)
  return(P_pay)
}

grid &lt;- matrix(sample(0:1, N * N, replace = TRUE, prob = c(0.5, 0.5)),
               nrow = N, ncol = N)

wrap &lt;- function(x, n) ((x - 1) %% n) + 1

get_neighbors &lt;- function(r, c, n) {
  list(
    c(wrap(r - 1, n), c),
    c(wrap(r + 1, n), c),
    c(r, wrap(c - 1, n)),
    c(r, wrap(c + 1, n))
  )
}

coop_history &lt;- numeric(n_rounds + 1)
coop_history[1] &lt;- mean(grid)

snapshots &lt;- list()
snapshots[[1]] &lt;- grid

for (round in 1:n_rounds) {
  payoffs &lt;- matrix(0, N, N)
  for (r in 1:N) {
    for (cc in 1:N) {
      nbrs &lt;- get_neighbors(r, cc, N)
      for (nb in nbrs) {
        payoffs[r, cc] &lt;- payoffs[r, cc] +
          pd_payoff(grid[r, cc], grid[nb[1], nb[2]])
      }
    }
  }

  new_grid &lt;- grid
  for (r in 1:N) {
    for (cc in 1:N) {
      best_payoff &lt;- payoffs[r, cc]
      best_strategy &lt;- grid[r, cc]
      nbrs &lt;- get_neighbors(r, cc, N)
      for (nb in nbrs) {
        if (payoffs[nb[1], nb[2]] &gt; best_payoff) {
          best_payoff &lt;- payoffs[nb[1], nb[2]]
          best_strategy &lt;- grid[nb[1], nb[2]]
        }
      }
      new_grid[r, cc] &lt;- best_strategy
    }
  }
  grid &lt;- new_grid
  coop_history[round + 1] &lt;- mean(grid)

  if (round %in% c(10, 50, 100)) {
    snapshots[[length(snapshots) + 1]] &lt;- grid
  }
}

