cat(sprintf("\nOptimal US strategy:\n  p &lt; %.1f%%: Blockade (force withdrawal)\n  p &gt; %.1f%%: Negotiate (avoid escalation risk)\n",
            100 * p_cross_bn, 100 * p_cross_bn))


