find_nash_mixed &lt;- function(a, b, c, d, e, f, g, h) {
  denom_p &lt;- e - f - g + h
  denom_q &lt;- a - b - c + d
  p_star &lt;- if (abs(denom_p) &gt; 1e-10) (h - f) / denom_p else NA_real_
  q_star &lt;- if (abs(denom_q) &gt; 1e-10) (d - b) / denom_q else NA_real_
  if (!is.na(p_star) && !is.na(q_star) &&
      p_star &gt;= 0 && p_star &lt;= 1 && q_star &gt;= 0 && q_star &lt;= 1) {
    return(data.frame(p = p_star, q = q_star, type = "Mixed"))
  }
  return(data.frame(p = NA_real_, q = NA_real_, type = "None"))
}

