set.seed(42)

L &lt;- 50
n_steps &lt;- 80
b_param &lt;- 1.65

grid &lt;- matrix(sample(c(1, 0), L * L, replace = TRUE, prob = c(0.5, 0.5)),
               nrow = L, ncol = L)

get_neighbors &lt;- function(i, j, L) {
  rows &lt;- ((i - 2):(i)) %% L + 1
  cols &lt;- ((j - 2):(j)) %% L + 1
  expand.grid(row = rows, col = cols)
}

compute_payoffs &lt;- function(grid, b, L) {
  payoffs &lt;- matrix(0, nrow = L, ncol = L)
  for (i in 1:L) {
    for (j in 1:L) {
      nb &lt;- get_neighbors(i, j, L)
      total &lt;- 0
      for (k in 1:nrow(nb)) {
        ni &lt;- nb$row[k]
        nj &lt;- nb$col[k]
        if (grid[i, j] == 1 && grid[ni, nj] == 1) total &lt;- total + 1
        if (grid[i, j] == 0 && grid[ni, nj] == 1) total &lt;- total + b
      }
      payoffs[i, j] &lt;- total
    }
  }
  return(payoffs)
}

update_grid &lt;- function(grid, payoffs, L) {
  new_grid &lt;- matrix(0, nrow = L, ncol = L)
  for (i in 1:L) {
    for (j in 1:L) {
      nb &lt;- get_neighbors(i, j, L)
      best_payoff &lt;- -Inf
      best_strategy &lt;- grid[i, j]
      for (k in 1:nrow(nb)) {
        ni &lt;- nb$row[k]
        nj &lt;- nb$col[k]
        if (payoffs[ni, nj] &gt; best_payoff) {
          best_payoff &lt;- payoffs[ni, nj]
          best_strategy &lt;- grid[ni, nj]
        }
      }
      new_grid[i, j] &lt;- best_strategy
    }
  }
  return(new_grid)
}

