# ============================================================
# PART 1: Support Enumeration in Pure R
# ============================================================

# --- Generate subsets of size k from 1:n ---
combn_list &lt;- function(n, k) {
  if (k &gt; n || k &lt; 1) return(list())
  as.list(as.data.frame(combn(n, k)))
}

# --- Support enumeration solver ---
support_enumeration &lt;- function(A, B, tol = 1e-10) {
  m &lt;- nrow(A)
  n &lt;- ncol(A)
  equilibria &lt;- list()

  for (k in 1:min(m, n)) {
    supports_1 &lt;- combn_list(m, k)
    supports_2 &lt;- combn_list(n, k)

    for (s1 in supports_1) {
      for (s2 in supports_2) {
        # Solve for q: A[s1, s2] %*% q = v1 * 1, sum(q) = 1
        A_sub &lt;- A[s1, s2, drop = FALSE]
        B_sub &lt;- B[s1, s2, drop = FALSE]

        # Augmented system for q
        M_q &lt;- rbind(A_sub, rep(1, k))
        # We need to find q and v1 such that A_sub %*% q = v1 * 1, sum(q) = 1
        # Rewrite: [A_sub, -1] [q; v1] = [0; ...], [1,...,1, 0] [q; v1] = 1
        if (k == 1) {
          q &lt;- 1
          v1 &lt;- A_sub[1, 1]
        } else {
          M &lt;- rbind(
            cbind(A_sub, -rep(1, k)),
            c(rep(1, k), 0)
          )
          rhs &lt;- c(rep(0, k), 1)
          sol_q &lt;- tryCatch(solve(M, rhs), error = function(e) NULL)
          if (is.null(sol_q)) next
          q &lt;- sol_q[1:k]
          v1 &lt;- sol_q[k + 1]
        }

        # Solve for p: B[s1, s2]^T %*% p = v2 * 1, sum(p) = 1
        if (k == 1) {
          p &lt;- 1
          v2 &lt;- B_sub[1, 1]
        } else {
          M2 &lt;- rbind(
            cbind(t(B_sub), -rep(1, k)),
            c(rep(1, k), 0)
          )
          rhs2 &lt;- c(rep(0, k), 1)
          sol_p &lt;- tryCatch(solve(M2, rhs2), error = function(e) NULL)
          if (is.null(sol_p)) next
          p &lt;- sol_p[1:k]
          v2 &lt;- sol_p[k + 1]
        }

        # Check: all probabilities non-negative
        if (any(p &lt; -tol) || any(q &lt; -tol)) next

        # Check: strategies outside support give lower payoff
        p_full &lt;- rep(0, m); p_full[s1] &lt;- pmax(p, 0)
        q_full &lt;- rep(0, n); q_full[s2] &lt;- pmax(q, 0)

        payoffs_1 &lt;- A %*% q_full
        payoffs_2 &lt;- t(B) %*% p_full

        if (any(payoffs_1[-s1] &gt; v1 + tol)) next
        if (any(payoffs_2[-s2] &gt; v2 + tol)) next

        equilibria[[length(equilibria) + 1]] &lt;- list(
          p = p_full, q = q_full,
          v1 = v1, v2 = v2,
          support_1 = s1, support_2 = s2
        )
      }
    }
  }
  equilibria
}

