# --- Naive (loop-based) fictitious play ---
fictitious_play_naive &lt;- function(A, B, n_iter = 2000) {
  m &lt;- nrow(A); n &lt;- ncol(A)
  counts_1 &lt;- rep(0, m)  # action counts for player 1
  counts_2 &lt;- rep(0, n)  # action counts for player 2

  exploitability &lt;- numeric(n_iter)

  for (t in 1:n_iter) {
    # Empirical strategies
    p_bar &lt;- if (sum(counts_1) &gt; 0) counts_1 / sum(counts_1) else rep(1/m, m)
    q_bar &lt;- if (sum(counts_2) &gt; 0) counts_2 / sum(counts_2) else rep(1/n, n)

    # Best responses (computed element-by-element)
    payoffs_1 &lt;- numeric(m)
    for (i in 1:m) {
      for (j in 1:n) {
        payoffs_1[i] &lt;- payoffs_1[i] + A[i, j] * q_bar[j]
      }
    }
    br_1 &lt;- which.max(payoffs_1)

    payoffs_2 &lt;- numeric(n)
    for (j in 1:n) {
      for (i in 1:m) {
        payoffs_2[j] &lt;- payoffs_2[j] + B[i, j] * p_bar[i]
      }
    }
    br_2 &lt;- which.max(payoffs_2)

    counts_1[br_1] &lt;- counts_1[br_1] + 1
    counts_2[br_2] &lt;- counts_2[br_2] + 1

    # Exploitability
    exploitability[t] &lt;- max(payoffs_1) + max(payoffs_2) -
      sum(p_bar * (A %*% q_bar)) - sum(q_bar * (t(B) %*% p_bar))
  }

  list(p = counts_1 / sum(counts_1),
       q = counts_2 / sum(counts_2),
       exploitability = exploitability)
}

# --- Vectorised fictitious play ---
fictitious_play_vec &lt;- function(A, B, n_iter = 2000) {
  m &lt;- nrow(A); n &lt;- ncol(A)
  counts_1 &lt;- rep(0, m)
  counts_2 &lt;- rep(0, n)

  exploitability &lt;- numeric(n_iter)

  for (t in 1:n_iter) {
    p_bar &lt;- if (sum(counts_1) &gt; 0) counts_1 / sum(counts_1) else rep(1/m, m)
    q_bar &lt;- if (sum(counts_2) &gt; 0) counts_2 / sum(counts_2) else rep(1/n, n)

    # Vectorised best responses
    payoffs_1 &lt;- as.vector(A %*% q_bar)
    br_1 &lt;- which.max(payoffs_1)

    payoffs_2 &lt;- as.vector(t(B) %*% p_bar)
    br_2 &lt;- which.max(payoffs_2)

    counts_1[br_1] &lt;- counts_1[br_1] + 1
    counts_2[br_2] &lt;- counts_2[br_2] + 1

    exploitability[t] &lt;- max(payoffs_1) + max(payoffs_2) -
      sum(p_bar * (A %*% q_bar)) - sum(q_bar * (t(B) %*% p_bar))
  }

  list(p = counts_1 / sum(counts_1),
       q = counts_2 / sum(counts_2),
       exploitability = exploitability)
}

