R implementation
We implement a support enumeration solver and a comprehensive test harness. The solver iterates over all possible support pairs, solves the resulting linear systems, and returns valid equilibria. The test functions verify the core equilibrium conditions programmatically.

set.seed(42)

# --- Nash equilibrium solver via support enumeration ---
solve_nash_support &lt;- function(A, B, tol = 1e-10) {
  m &lt;- nrow(A); n &lt;- ncol(A)
  equilibria &lt;- list()
  for (s1_size in 1:m) {
    for (s2_size in 1:n) {
      s1_combos &lt;- combn(m, s1_size, simplify = FALSE)
      s2_combos &lt;- combn(n, s2_size, simplify = FALSE)
      for (s1 in s1_combos) {
        for (s2 in s2_combos) {
          result &lt;- tryCatch({
            B_sub &lt;- B[s1, s2, drop = FALSE]
            A_sub &lt;- A[s1, s2, drop = FALSE]
            # Player 2's mix makes player 1 indifferent on support
            if (s2_size == 1) { y_sub &lt;- 1 }
            else {
              M2 &lt;- t(A_sub[, -s2_size, drop = FALSE] - A_sub[, s2_size])
              rhs2 &lt;- rep(0, s2_size - 1)
              if (nrow(M2) &gt; 0 && ncol(M2) &gt; 0) {
                y_partial &lt;- tryCatch(solve(cbind(M2, 1), c(rhs2, 1)),
                                      error = function(e) NULL)
                if (is.null(y_partial)) next
                y_sub &lt;- y_partial[1:(s2_size)]
              } else { y_sub &lt;- 1 }
            }
            if (s1_size == 1) { x_sub &lt;- 1 }
            else {
              M1 &lt;- t(t(B_sub)[-s1_size, , drop = FALSE] - t(B_sub)[s1_size, ])
              rhs1 &lt;- rep(0, s1_size - 1)
              if (nrow(M1) &gt; 0 && ncol(M1) &gt; 0) {
                x_partial &lt;- tryCatch(solve(cbind(M1, 1), c(rhs1, 1)),
                                      error = function(e) NULL)
                if (is.null(x_partial)) next
                x_sub &lt;- x_partial[1:(s1_size)]
              } else { x_sub &lt;- 1 }
            }
            if (any(x_sub &lt; -tol) || any(y_sub &lt; -tol)) next
            x &lt;- rep(0, m); y &lt;- rep(0, n)
            x[s1] &lt;- pmax(x_sub, 0); y[s2] &lt;- pmax(y_sub, 0)
            x &lt;- x / sum(x); y &lt;- y / sum(y)
            list(x = x, y = y)
          }, error = function(e) NULL)
          if (!is.null(result)) equilibria[[length(equilibria) + 1]] &lt;- result
        }
      }
    }
  }
  equilibria
}

# --- Test functions ---
check_simplex &lt;- function(p, tol = 1e-8) {
  all(p &gt;= -tol) && abs(sum(p) - 1) &lt; tol
}

compute_regret &lt;- function(A, B, x, y) {
  payoff1 &lt;- as.numeric(t(x) %*% A %*% y)
  payoff2 &lt;- as.numeric(t(x) %*% B %*% y)
  max_dev1 &lt;- max(A %*% y)
  max_dev2 &lt;- max(t(B) %*% x)
  c(r1 = max_dev1 - payoff1, r2 = max_dev2 - payoff2)
}

# --- Test suite ---
test_cases &lt;- list(
  list(name = "Matching Pennies", A = matrix(c(1,-1,-1,1), 2, 2),
       B = matrix(c(-1,1,1,-1), 2, 2), x_exp = c(0.5, 0.5), y_exp = c(0.5, 0.5)),
  list(name = "Prisoners Dilemma", A = matrix(c(3,0,5,1), 2, 2),
       B = matrix(c(3,5,0,1), 2, 2), x_exp = c(0, 1), y_exp = c(0, 1)),
  list(name = "Pure Coordination", A = matrix(c(2,0,0,1), 2, 2),
       B = matrix(c(2,0,0,1), 2, 2), x_exp = c(1, 0), y_exp = c(1, 0)),
  list(name = "Zero Matrix", A = matrix(0, 2, 2),
       B = matrix(0, 2, 2), x_exp = c(0.5, 0.5), y_exp = c(0.5, 0.5))
)

tol_levels &lt;- c(1e-6, 1e-8, 1e-10, 1e-12)
results &lt;- data.frame()

for (tc in test_cases) {
  for (tol in tol_levels) {
    eqs &lt;- solve_nash_support(tc$A, tc$B, tol = tol)
    n_found &lt;- length(eqs)
    simplex_ok &lt;- if (n_found &gt; 0) all(sapply(eqs, function(e)
      check_simplex(e$x) && check_simplex(e$y))) else FALSE
    regret_ok &lt;- if (n_found &gt; 0) {
      min_regret &lt;- min(sapply(eqs, function(e)
        max(compute_regret(tc$A, tc$B, e$x, e$y))))
      min_regret &lt; 1e-6
    } else FALSE
    results &lt;- rbind(results, data.frame(
      game = tc$name, tolerance = tol, n_equilibria = n_found,
      simplex_valid = simplex_ok, regret_valid = regret_ok,
      test_pass = simplex_ok & regret_ok, stringsAsFactors = FALSE))
  }
}

